import{a as p,b as g,c as A}from"./chunks/chunk-EWNQBASX.js";import{B as v,F as Z,J as k,N as S,R as x,V as j,Z as T,g as P,h as L,k as u,l as m,p as f,t as y,x as w}from"./chunks/chunk-HNNVAFRB.js";import"./chunks/chunk-VC46IEJQ.js";var z={abandon:{soundZh:"中文谐音联想：abandon ≈ ‘啊，band（乐队）！’。先喊出这支 band，再看它演完把乐器全扔在台上。注意：这是中英混合记忆法，不是词源。",rootZh:"来自法语 abandonner。现代学习时不要把它硬拆成 a + band + on；这里没有可靠、实用的现代英语词根拆分。",englishHookZh:"英文近音钩子 a band on stage：A band played with abandon, then abandoned its instruments. 一支乐队同时串起‘尽情地’和‘遗弃’。",formZh:"词源上来自法语 abandonner；a band 只能作声音联想，不能当词根。",sceneZh:"一支乐队彻底松开控制，疯了一样演奏；散场后又彻底松手，把吉他、鼓和音箱全遗弃在台上。",bridgeZh:"抓住‘彻底松手’：对东西松手＝放弃、抛弃；对自我约束松手＝with abandon，无拘无束地。",trapZh:"with abandon 不是‘带着放弃’，而是‘尽情地’；withdraw 常只是撤回或退出，abandon 更像彻底不管了。",microEn:"A band played with abandon, then abandoned every instrument onstage.",microZh:"一支乐队尽情演奏，随后把所有乐器遗弃在台上。"},abase:{soundZh:"中文谐音联想：abase ≈ ‘啊，卑死！’——一个人卑微到跪在王座底座旁。谐音只帮你叫出声音，不是真实词源。",rootZh:"经由古法语 abaisser，核心就是‘使降低’；它与表示‘低、底部’的 base/bass 词族有历史联系。把 a + base 当图像可以，但不要当严格的现代构词分析。",englishHookZh:"熟词 base＝底部。想象把一个人的地位压到 base，降低的不是椅子，而是他的身份和尊严。",formZh:"base＝底部是可靠的词族线索；a + base 适合记形，但不是严格拆词。",sceneZh:"国王按下按钮，大臣连人带尊严一起降到王座的 base，最后只能趴在地上奉承。",bridgeZh:"从‘压到最低处’推出：abase 专门压低人的地位、尊严或自我评价。",trapZh:"lower 可降低价格、声音、平台；abase 通常作用于人或人的尊严。高频结构是 abase oneself before someone。",microEn:"The minister refused to abase himself before the emperor.",microZh:"大臣拒绝在皇帝面前卑躬屈膝、自降人格。"},abash:{soundZh:"中文谐音联想：abash ≈ ‘啊，被嘘！’——刚开口就被全场嘘，脸红得立刻失去自信。这里只是近似声音联想。",rootZh:"来自古法语中表示‘使惊愕、使不知所措’的词。现代英语里无可靠的 a + bash 拆分，勿把 bash 当词根。",englishHookZh:"英文近音 at a bash：在 bash（聚会）上童年糗照被公开，you feel abashed。bash 只是声音钩子，不是同源解释。",formZh:"无可靠现代拆分；at a bash 是近音记忆，不是词源。",sceneZh:"聚会上大屏幕突然播放你跑调的视频，全场一起‘嘘——’，你的自信气球啪地瘪了。",bridgeZh:"‘被嘘后失去镇定’把声音连到词义：abash 是使人羞愧、窘迫，常伴随自信受挫。",trapZh:"现代英语更常见 abashed。embarrassed 范围更广；abashed 更正式，更突出羞愧后局促、失去镇定。",microEn:"At the bash, an old video left the confident singer abashed.",microZh:"聚会上的一段旧录像让自信的歌手顿时窘迫。"},abate:{soundZh:"中文谐音联想：abate ≈ ‘阿伯退’——风暴太猛，阿伯把强度旋钮往后退，风声立刻减弱。谐音不是词源。",rootZh:"经古法语 abatre 而来，原始图像接近‘击倒、压下’；因此很自然地发展为强度下降、减弱。",englishHookZh:"熟词桥 bated breath：with bated breath 是‘屏息地’，其中 bated 有‘收住、减弱’的意思，可把它和 abate 一起记。",formZh:"古法语 abatre 的核心图像是把力量压下去；bated breath 可作同族用法钩子。",sceneZh:"阿伯和风暴拔河，终于把写着 INTENSITY 的巨大推杆往下压，雷声、疼痛和怒火一起减弱。",bridgeZh:"把力量‘压下去’＝风暴、疼痛、噪声或愤怒的强度 abates。",trapZh:"abate 可不及物：The storm abated；reduce 通常及物：The walls reduced the noise。不要机械地说 abate the value。",microEn:"As the storm abated, the sailors stopped waiting with bated breath.",microZh:"风暴减弱后，水手们终于不再屏息等待。"},abbreviate:{soundZh:"中英混合声音联想：abbreviate ≈ ‘啊，brief 一下！’——编辑嫌标题太长，命令把它弄得 brief。这里只是发音入口。",rootZh:"可靠词根 brev/brevi 来自拉丁语 brevis＝short。brief、brevity、abbreviation 都能帮助确认‘短’这个核心。",englishHookZh:"熟词 brief＝简短的。abbreviate 就是 make a word, name, or expression briefer。",formZh:"brev/brevi＝short；同族有 brief、brevity、abbreviation。",sceneZh:"编辑挥着写有 BRIEF 的剪刀，把 Artificial Intelligence 的长纸条剪成 AI。",bridgeZh:"brev＝短，所以 abbreviate 是把名称、单词或表达缩短，常缩成字母形式。",trapZh:"abbreviate a name as/to...；abridge 是删节长文本，summarize 是用自己的话概括主旨。",microEn:"The editor abbreviated the enormous title to three letters.",microZh:"编辑把长得离谱的标题缩成了三个字母。"},abdicate:{soundZh:"中文情节谐音：abdicate ≈ ‘阿伯当帝？退！’——阿伯刚坐上王位就摘下王冠退位。谐音只负责唤起画面。",rootZh:"来自拉丁语 abdicare：ab-＝away，加上与‘宣告、声明’有关的 dic/dicāre，原图像是正式宣告放弃。",englishHookZh:"熟词 dictionary、dictate 都能提示 dic/dict 与‘说、宣布’有关：公开说自己离开王位，就是 abdicate。",formZh:"ab-＝away；dic/dict 提示 say/declare：正式宣布离开权位。",sceneZh:"‘阿伯皇帝’站在全国镜头前大声宣布：王冠不要了，保护巨龙的责任我也不管了。",bridgeZh:"正式‘宣布离开’王位＝退位；把本应承担的重大责任也丢下＝abdicate responsibility。",trapZh:"resign 可用于普通职位；abdicate 最典型是王位，也可批评某人逃避重大责任。",microEn:"The king abdicated the throne but could not abdicate responsibility for the realm.",microZh:"国王退了位，却不能逃避对国家的责任。"},aberrant:{soundZh:"中英混合谐音：aberrant ≈ ‘阿伯 err 了’——阿伯一走错，火车就偏离正常轨道。err 是声音和意义的双重钩子。",rootZh:"来自拉丁语 aberrare：ab-＝away，errare＝wander/go astray。err、error 能帮你记住‘走错、偏离’。",englishHookZh:"熟词 err＝犯错，error＝错误。把正常轨道看作标准，err away from it 的结果就是 aberrant。",formZh:"ab-＝away；err＝wander/go wrong：从正常路线走偏。",sceneZh:"阿伯本该驾驶火车直行，却在地图上画了一个 ERROR，整列车冲出轨道，异常数据点也跟着飞出去。",bridgeZh:"从正常路线、规则或模式‘走偏’＝aberrant behavior / an aberrant result。",trapZh:"atypical 只是非典型，未必有问题；aberrant 往往含偏离规范、反常或异常的判断。",microEn:"One aberrant data point wandered far from the normal pattern.",microZh:"一个异常数据点远远偏离了正常模式。"},abet:{soundZh:"英文近音式联想：abet 听起来像 a bet。坏人设下一场赌局，激同伙去犯罪。a bet 不是词源，只是声音记忆。",rootZh:"经古法语中表示‘煽动、怂恿’的词进入英语。现代拼写没有值得学习的可靠拆分，尤其不要把 a bet 当词根。",englishHookZh:"a bet＝一场赌。想象赌徒说‘我赌你不敢偷’，再递钥匙、放哨；这已不是中性 help，而是 abet。",formZh:"无可靠现代英语拆分；a bet 是近音钩子，不是真实构词。",sceneZh:"一场赌局给小偷每个坏主意发奖金，赌徒还递钥匙、画地图、在门口放哨。",bridgeZh:"支持或鼓励的对象一旦是犯罪或坏事，普通 assist/encourage 就染上负面，变成 abet。",trapZh:"高频搭配 aid and abet。帮助同学学习不能用 abet；它通常暗示协助或教唆不法行为。",microEn:"A reckless bet abetted the thief by rewarding every crime.",microZh:"一个鲁莽赌局奖励每次犯罪，从而助长了小偷。"},abeyance:{soundZh:"中文谐音联想：abeyance ≈ ‘阿贝按死’——阿贝把暂停键按死，项目不取消，只暂时不动。谐音不是词源。",rootZh:"来自盎格鲁法语，早期含‘张口等待、期待’的意味。现代英语中无可靠实用的 a + bay 拆分，勿硬拆。",englishHookZh:"英文近音 a bay：船停在 bay 里等待，既没有报废也没继续出航，正像 a project held in abeyance。",formZh:"无可靠现代拆分；a bay 是近音画面，不是词源。",sceneZh:"阿贝按下巨大的暂停键，一艘项目船立刻停在海湾：引擎没拆，航程没取消，只等重新启动。",bridgeZh:"暂停键＋等待复航＝暂时搁置、暂停生效，而不是永久取消。",trapZh:"几乎总在 in abeyance / hold something in abeyance 中出现；abeyance 不等于 cancellation。",microEn:"The project remained in abeyance like a ship waiting in a bay.",microZh:"项目像停在海湾等待的船一样，处于暂时搁置状态。"},abhor:{soundZh:"中文近似谐音：abhor ≈ ‘啊，不好！’——看到虐待行为时把‘不好’喊得又重又长，并本能后退。谐音只是入口。",rootZh:"来自拉丁语 abhorrere：ab-＝away，horrere＝shudder/bristle（战栗、毛发竖起）。horror 与它共享可靠的词根线索。",englishHookZh:"熟词 horror＝恐怖。面对令人憎恶之物，厌恶到像见到 horror 一样战栗，就是 abhor。",formZh:"ab-＝away；hor/horr＝shudder：厌恶得战栗并躲开。",sceneZh:"一个人看到残忍行为，大喊‘啊，不好！’，全身像恐怖片里那样汗毛竖起，连退三步。",bridgeZh:"horror 式的战栗＋远离动作，把普通 dislike 推到‘深恶痛绝’。",trapZh:"abhor 是动词，abhorrent 是‘令人憎恶的’；程度远强于 dislike，也不要写 very abhor。",microEn:"She abhorred cruelty; the very thought made her shudder in horror.",microZh:"她深恶痛绝残忍行为；仅仅想到它就厌恶得战栗。"},abiding:{soundZh:"中文谐音联想：abiding ≈ ‘爱不败的’——不败的爱经得住时间，所以是持久的爱。谐音不是词源。",rootZh:"由 abide＋-ing 构成。abide 的核心之一是 remain/stay，因此 abiding 自然表示 continuing for a long time。",englishHookZh:"熟词短句 love abides＝爱长存。把 abide 的‘留下、持续’变成形容词，就是 abiding love。",formZh:"abide＝remain/stay；-ing 构成形容词：长期持续的。",sceneZh:"一颗写着‘爱不败’的心经历暴雨、十年和一只捣乱鹦鹉，仍牢牢钉在原地。",bridgeZh:"能够一直 abide、留存不去的感情、兴趣或信念，就是 abiding。",trapZh:"abiding 常修饰 love、interest、faith、memory，带深厚持久感；permanent 更客观，不一定有感情色彩。",microEn:"Her abiding love survived time, distance, and every storm.",microZh:"她持久的爱经受住了时间、距离和每一场风暴。"},abject:{soundZh:"中文谐音联想：abject ≈ ‘挨不接’——谁都不肯接纳他，他像被扔到最底层，处境悲惨又卑微。谐音不是词源。",rootZh:"可靠构词线索：ab-＝away/down，ject 来自拉丁语 jacere＝throw。字面图像是‘被扔开、扔下去’。",englishHookZh:"熟词 inject、reject、eject 都含 ject＝throw：reject 是扔回，eject 是扔出，abject 是被扔到低处。",formZh:"ab-＝away/down；ject＝throw：被扔到最低处。",sceneZh:"‘挨不接’先生被所有人拒绝，连人带尊严被巨手扔进写着 POVERTY 的地下室。",bridgeZh:"从‘被扔到低处’展开三条义线：处境极惨、精神极度低落、态度卑躬屈膝。",trapZh:"abject poverty/failure/terror 表示极端程度；humble 可是美德，abject humility 往往是屈从和自轻。",microEn:"In abject poverty, the proud duke made an abject apology.",microZh:"骄傲的公爵陷入赤贫，还作出了卑微屈从的道歉。"},abjure:{soundZh:"中文谐音联想：abjure ≈ ‘阿伯拒！’——阿伯举手发誓：我拒绝旧信念，永不再碰。谐音不是词源。",rootZh:"来自拉丁语 abjurare：ab-＝away，jurare＝swear。jur/jur 还出现在 jury、juror 等与宣誓或法律有关的词中。",englishHookZh:"熟词 jury / juror 提醒 jur 与法律、宣誓有关。不是随口 say no，而是 swear away，郑重放弃。",formZh:"ab-＝away；jur＝swear：发誓离开、郑重放弃。",sceneZh:"阿伯站在法庭上举手大喊‘拒！’，随后把旧信念锁进箱子，并当众宣誓再也不用。",bridgeZh:"‘举手发誓＋拒绝’把 reject/abandon 升级为公开、郑重的 abjure。",trapZh:"abjure 常直接接信念、暴力、习惯等；resist 只是抵制诱惑，abjure 是郑重宣布彻底放弃。",microEn:"The wizard solemnly abjured magic and returned every wand.",microZh:"巫师郑重宣誓放弃魔法，并归还了所有魔杖。"},abnegate:{soundZh:"中文谐音联想：abnegate ≈ ‘阿伯：那个也不要！’——阿伯把享受、权利和王冠全推给别人。谐音只用于唤起画面。",rootZh:"来自拉丁语 abnegare：ab-＝away，negare＝deny。neg 是否定线索，也见于 negate、negative。",englishHookZh:"熟词 negate＝否定，negative＝否定的。abnegate 像把自己的欲望或权利说成‘不’，再实际放弃。",formZh:"ab-＝away；neg＝deny/no：否定并放弃自己的欲望或权利。",sceneZh:"宴会上，阿伯边喊‘那个也不要！’边推走蛋糕、软椅和王冠，最后把自己的特权也交给别人。",bridgeZh:"先对自我欲望说 no，再交出利益或权利＝克制、舍弃、放弃。",trapZh:"self-abnegation 常指克己牺牲；abnegate responsibility 则可能是推卸责任。它不只是口头 deny，还可含实际 relinquish。",microEn:"The monk abnegated comfort and relinquished every privilege.",microZh:"僧侣克制享受，放弃了所有特权。"},abominate:{soundZh:"中文谐音联想：abominate ≈ ‘阿伯骂你呢’——阿伯不是普通抱怨，而是厌恶到指着坏事大骂。谐音不是词源。",rootZh:"来自拉丁语 abominari，早期图像是把某事视为不祥之兆而排斥；其中 omen（预兆）是有用的历史线索。不要按现代拼写随意拆。",englishHookZh:"熟词 abominable＝令人憎恶的。先记更常见的形容词，再反推动词 abominate＝极度憎恶。",formZh:"历史上与 omen（预兆）有关；现代最实用的词族桥是 abominable。",sceneZh:"阿伯看到一块写着‘不祥之兆’的恶臭牌子，捂着鼻子破口大骂，恨不得把它扔出城。",bridgeZh:"把某物视为恶臭的不祥之物，产生强烈排斥＝abominate，程度接近 abhor。",trapZh:"abominate 是较正式、较少见的动词；abominable 才是‘令人憎恶的’，不要混淆词性。",microEn:"The tidy ghost abominated dust, disorder, and careless haunting.",microZh:"爱整洁的幽灵极度憎恶灰尘、混乱和敷衍的闹鬼。"},aboveboard:{soundZh:"中英混合声音联想：aboveboard 就按字面喊成‘above the board’——牌和双手全在桌面上方，无处作弊。这是构词本身，不必强造中文谐音。",rootZh:"透明复合词 above＋board。常用牌桌图像理解：动作都在桌面之上，看得见、无隐藏，于是引申为诚实正当。",englishHookZh:"两个熟词直接成像：above＝在上方，board＝桌板。If every move is above the board, the deal is aboveboard。",formZh:"above＋board：牌桌上方没有隐藏动作，因此光明正大。",sceneZh:"牌手把牌、钱和双手都举到 board 上方，连袖口都透明，所有人一眼看清，完全无法欺骗。",bridgeZh:"从‘没有藏在桌下’推出：公开、诚实、没有 deceit or duplicity。",trapZh:"transparent 侧重信息可见、可审查；aboveboard 更直接评价行为诚实正当。公开不自动等于合规，需看语境。",microEn:"With every card above the board, the strange deal was completely aboveboard.",microZh:"所有牌都摆在桌面上，这笔奇怪交易完全光明正大。"},abrade:{soundZh:"中文谐音联想：abrade ≈ ‘阿伯累得’——阿伯不停摩擦石头，累得把表面都磨掉一层。谐音不是词源。",rootZh:"来自拉丁语 abradere：ab-＝away，radere＝scrape/shave。核心机制是靠摩擦刮走、磨走表层。",englishHookZh:"熟词 abrasion＝擦伤、磨损，是最可靠的同族桥；blade 只与 abrade 近音，不是它的词根。",formZh:"ab-＝away；rad＝scrape/shave；同族词 abrasion。",sceneZh:"阿伯累得满头大汗，还用粗砂纸反复蹭招牌，直到每个油漆字母都被磨掉。",bridgeZh:"反复 friction 把表层一点点带走＝abrade；也可比喻长期消磨耐心或精神。",trapZh:"scrape 可指一次刮擦；abrade 更常指摩擦造成的持续磨损。a blade 是近音画面，不是真实词源。",microEn:"The rough rope abraded the rock and left a deep groove.",microZh:"粗糙的绳子不断摩擦岩石，磨出了一道深槽。"},abridge:{soundZh:"中文谐音联想：abridge ≈ ‘阿伯只……’——阿伯读长书时只留主线，把其余段落删掉。谐音不是词源。",rootZh:"经法语进入英语，最终与拉丁语 brevis＝short 有关，和 abbreviate 共享‘变短’的历史线索。它不是 a＋bridge。",englishHookZh:"英文近音 a bridge：把一座绕远的长桥截短，却仍让人到达同一终点。bridge 只是声音图像，不是真实词根。",formZh:"最终与 brevis＝short 有关；a bridge 是近音记忆，不是构词。",sceneZh:"阿伯拿剪刀剪掉长桥的所有弯路，只保留通往同一终点的主桥；一本厚书也被他剪成短版。",bridgeZh:"删掉部分、缩短长度，但仍保留原作主线和意义＝abridge。",trapZh:"abbreviate 多缩短词语或名称；abridge 多删节书文，也可表示削减权利；summarize 是重新概括。",microEn:"The editor abridged the novel without destroying its central argument.",microZh:"编辑删节了小说，同时保留了它的核心论旨。"},abrogate:{soundZh:"中文谐音联想：abrogate ≈ ‘阿伯若盖它’——阿伯若在旧法上盖‘作废’章，它就正式失效。谐音不是词源。",rootZh:"来自拉丁语 abrogare：ab-＝away，rogare＝ask/propose；在法律语境中发展出正式撤销、废除的意思。",englishHookZh:"英文近音 a broken gate：一扇被判作废的 broken gate 不再执行原来的通行规则。它只是声音场景；真正近义桥是 repeal / annul。",formZh:"拉丁语 abrogare 指正式撤销；现代学习用 repeal、annul 作可靠语义桥。",sceneZh:"阿伯若盖下红色‘ABROGATED’印章，法典中的旧法立刻变灰，从那一刻起不再生效。",bridgeZh:"由有权机构正式让法律、协议或规定失效＝abrogate，不只是暂时不执行。",trapZh:"abdicate 是人放弃王位或责任；abrogate 是废除法律、协议、权利或义务。取消普通预约通常不用它。",microEn:"Parliament abrogated the obsolete law with one formal vote.",microZh:"议会通过一次正式表决废除了那项过时法律。"},abscond:{soundZh:"中文谐音联想：abscond ≈ ‘阿伯闪空’——一眨眼办公室空了，阿伯带着钱秘密逃走。谐音不是词源。",rootZh:"来自拉丁语 abscondere：abs-＝away，condere＝put/store/hide。原始图像是把自己藏起来、从视线中消失。",englishHookZh:"熟词组合 absent＋concealed：人先 absent，再 concealed。两步合起来就是 secretly leave and hide，接近 abscond。",formZh:"abs-＝away；condere＝hide/store：离开并藏起来。",sceneZh:"‘阿伯闪空’只留下一把转椅：他半夜提着钱袋溜走，又钻进地图外的秘密地洞。",bridgeZh:"secretly depart 之后还要 hide，常伴随逃避法律或携款潜逃，这才是 abscond 的完整动作。",trapZh:"高频搭配 abscond with money、abscond from custody、abscond to another country；它不是普通 leave。",microEn:"The treasurer absconded with the gold and hid beyond the border.",microZh:"财务主管携黄金潜逃，并躲到了边境之外。"}};var e=(a,t,...r)=>({title:a,explanation:t,phrases:r}),C={authentic:[e("来源真实、并非伪造","修饰 document、signature、artifact 等时，authentic 表示对象确实来自所声称的作者、年代或出处，能够通过来源核验。","an authentic document"),e("忠实于事实或传统","修饰 cuisine、account、performance 等时，表示内容或做法贴合真实经验、事实记录或传统规范。","authentic local cuisine","an authentic account")],authority:[e("某领域公认的权威人士","可数结构 an authority on... 指在特定领域知识深厚、判断受到承认的人。","an authority on"),e("合法的命令或决定权","不可数时常用 have authority to do 或 under the authority of，表示制度授予的管辖、指挥或批准权。","have authority to do something","under the authority of"),e("可靠的消息根据","固定结构 on good authority 表示信息来自可信而有资格知情的来源。","on good authority")],autocracy:[e("权力集中于一人的政体","autocracy 指最终政治权力由一个统治者掌握、缺少有效外部制约；可用于建立、实行或描述这种制度。","establish an autocracy","autocratic rule","be ruled as an autocracy")],autonomy:[e("自行治理或决策的权利","可用于地区、职业与个人，表示主体在既定范围内不受外部任意支配，能够依据自身规则作决定。","grant autonomy to","regional autonomy","professional autonomy","personal autonomy")],avarice:[e("对财富无止境的贪欲","正式且明显贬义，表示占有欲不断扩大，即使已有大量财富仍不满足。","driven by avarice","insatiable avarice","a display of avarice")],aver:[e("郑重断言某事为真","及物动词可接 that 从句或名词宾语，表示说话者明确坚持某项陈述、身份或清白是真实的。","aver that","aver one's innocence","firmly aver")],aversion:[e("强烈到促使人回避的厌恶","最稳定结构是 an aversion to；可描述厌恶逐渐形成、强度很高，也可把某人或事物称为 object of aversion。","an aversion to","develop an aversion","a strong aversion","an object of aversion")],avid:[e("持续而强烈地热衷","修饰 reader、collector 或 interest 时，表示主动投入、不断寻求更多相关经验或材料。","an avid reader","an avid interest in","an avid collector"),e("贪婪渴求利益","结构 avid for gain 把强烈热衷转为对金钱或利益的旺盛占有欲，通常带负面色彩。","avid for gain")],awash:[e("被水覆盖或漫过","可用 awash with water，也可让 decks 等表面作主语，表示水已经漫过并在表面流动。","awash with water","decks awash"),e("充斥大量信息或资源","比喻结构 awash with / in 表示某物多得像水一样泛滥，覆盖整个环境。","awash with rumors","awash in cash")],awe:[e("惊叹、敬畏与渺小感交织的感受","名词常见 in awe of、a sense of awe；对象通常宏大、强有力或令人难以完全理解。","in awe of","a sense of awe"),e("使人产生强烈敬畏","作动词可直接接人；inspire awe 则让人或事物作主语，说明其引发了敬畏。","inspire awe","awe the audience")],awkward:[e("动作笨拙或物体难操作","修饰 movement 时表示身体协调不顺；结构 awkward to handle 表示物体形状、重量或设计使操作不顺畅。","an awkward movement","awkward to handle"),e("场面或问题令人尴尬","修饰 silence、question 等时，表示参与者难以自然回应，社交气氛不顺或问题很难妥善处理。","an awkward silence","an awkward question")],awning:[e("门窗上方的遮阳雨篷","可伸缩或由帆布制成，固定在建筑外侧，用来挡住阳光或雨水；人在其下方可获得遮蔽。","a retractable awning","a canvas awning","sit under the awning")],awry:[e("位置歪斜","作形容词或副词描述物体没有摆正、偏离水平或正常方向。","hang awry"),e("计划偏离预期而出错","固定结构 go awry，常让 plans 等作主语，表示执行过程脱离原定路线并产生问题。","go awry","plans go awry")],axiomatic:[e("被视为无需证明的不言自明","常修饰 truth、principle，也可用 it is axiomatic that... 引出论证所接受的基本前提。","an axiomatic truth","an axiomatic principle","it is axiomatic that")],babble:[e("含混到难以理解地说话","不及物时可由 incoherently 修饰，表示话语因紧张、兴奋或能力限制而失去清楚结构；名词 babble 也可指这种难以辨清的话语声。","babble incoherently","a stream of babble"),e("喋喋不休地谈论琐事","接 about 时，babble 可指话语虽然能听懂，却冗长、轻浮而缺少重要内容。","babble about trivialities")],backhanded:[e("间接、迂回而不够坦率","修饰 method 等做法时，表示目标不是公开正面达成，而是通过隐蔽或不够光明的途径实现。","a backhanded method"),e("表面正面、实际含有贬低","常修饰 compliment、praise、apology，表示真正态度通过间接或反讽形式传出，表层措辞并不等于真实意图。","a backhanded compliment","backhanded praise","a backhanded apology")],badger:[e("反复纠缠直到对方让步","可用 badger someone for... 说明索求对象，或 badger someone into doing... 表示持续催逼最终促成行动。","badger someone for an answer","badger someone into agreeing","keep badgering someone")],badinage:[e("轻松机智的来回打趣","不可数名词，通常描述双方都参与、语气友善的诙谐闲谈；可用 exchange badinage 表示彼此接话。","light badinage","witty badinage","exchange badinage")],bait:[e("用于引诱进入圈套的诱饵","take the bait 表示受诱而上钩；use something as bait 则说明某物被摆出来吸引目标。","take the bait","use something as bait"),e("故意挑衅以诱发反应","及物接人并可接 into doing，表示有意用嘲弄或刺激让对方失去克制、作出预期反应。","bait someone into reacting")],bale:[e("文学语境中的痛苦或灾祸","古雅名词，常与 bliss 对举，或表示某人、某事把悲哀和祸患带给他人。","bliss and bale","bring bale upon","a world of bale")],baleful:[e("带来伤害、灾祸或威胁","可修饰 glare、influence、consequences；共同点是对象显露恶意或具有造成严重坏结果的力量。","a baleful glare","a baleful influence","baleful consequences")],balk:[e("临到要求前停住并拒绝","不及物固定接 at，表示面对提议、费用或行动要求时突然退缩，不肯继续。","balk at a proposal","balk at doing something"),e("阻挠他人的尝试","作及物动词接 attempt，表示设置障碍，使原本计划的行动无法成功。","balk an attempt"),e("妨碍行动的障碍","较少见的名词用法，相当于 hindrance 或 check，表示横在计划前、令进展受阻的人或事物。","a balk to progress")],balky:[e("顽固地拒绝运转或前进","可形容动物、机器或人，表示对象动不动就停住，不按操作者的要求继续。","a balky horse","a balky engine","become balky")],ballad:[e("用简朴诗节讲故事的歌谣","通常以叙事为中心，常有反复叠句；murder ballad 则围绕谋杀或死亡事件讲述故事。","a folk ballad","sing a ballad","a murder ballad")],balloon:[e("体积或数量迅速膨胀","作动词时常让 costs、debt 或 problem 作主语，表示像充气气球一样快速扩大，甚至发展成危机。","costs balloon","balloon from ... to ...","balloon into a crisis")],balm:[e("涂抹后舒缓伤处的香膏","可 apply balm to a wound；soothing 突出制剂能够缓和皮肤刺激或疼痛。","apply balm to a wound","a soothing balm"),e("缓解悲伤的安慰物","比喻结构 balm for grief 指能暂时安抚痛苦、让心情得到舒缓的人或事物。","balm for grief"),e("植物或树脂散发的芳香","文学性用法中，balm 可指温暖宜人的香气，常与草木、花园或芳香树脂相连。","fragrant balm")],banal:[e("因反复使用而陈腐平庸","常修饰 remark、plot，也可作表语 sound banal；重点是表达缺乏新意，不能再产生原有力量。","a banal remark","a banal plot","sound banal")],bane:[e("持续造成痛苦或毁坏的祸根","固定结构 the bane of... 指某人生活中反复制造麻烦的根源；也可更正式地表示有害甚至致命之物。","the bane of someone's existence","be a bane to","a deadly bane")],banish:[e("以命令强制驱逐","及物接人，可用 from 指明被逐出的地方，或 to 指明流放目的地。","banish someone from a country","banish someone to a distant island"),e("把抽象念头赶出心中","接 fear、doubt 等时，把驱逐动作转为彻底排除某种心理状态。","banish fear")],banter:[e("双方友善地来回逗趣","可作不可数名词，也可作动词接 with；交流应当是双向、轻松且双方可接受的。","friendly banter","exchange banter","banter with someone")],barb:[e("防止鱼钩或箭头脱出的倒钩","实体义指尖端向后伸出的锐刺；它会在进入后卡住，使钩子不易被拔出。","a backward-pointing barb"),e("短促而有意刺痛人的话","常见 barbed comment、trade barbs 或 a barb aimed at someone，把倒钩刺入皮肤的图像转为尖刻言辞。","a barbed comment","trade barbs","a barb aimed at someone")],barbarous:[e("残酷到违反人道或文明规范","常修饰 cruelty、custom、attack，对行为或制度作强烈道德谴责。","barbarous cruelty","a barbarous custom","a barbarous attack")],barefaced:[e("毫不遮掩地公然无耻","常修饰 lie、hypocrisy、attempt，表示行为人明知不当仍公开进行，完全不表现羞耻。","a barefaced lie","barefaced hypocrisy","a barefaced attempt")],bargain:[e("经协商达成的交换协议","strike a bargain 表示达成条件；keep your side of the bargain 表示履行自己在协议中的义务。","strike a bargain","keep your side of the bargain"),e("就交换条件讨价还价","作动词时常接 over，表示双方围绕价格或条件反复协商。","bargain over the price"),e("价格明显低于通常水平的便宜货","作可数名词时，a bargain 可指买得非常划算的人或物；判断核心是成交价相对于通常价值很低。","a real bargain")],baroque:[e("巴洛克式的繁复华丽","修饰 architecture、ornamentation 时，指装饰丰富、曲线复杂、视觉效果强烈的历史风格。","baroque architecture","baroque ornamentation"),e("结构曲折、过度雕琢","修饰 scheme、prose 或 arrangement 时，把繁复风格转为结构过度复杂、难以直接理解。","a baroque scheme")],barrage:[e("短时间连续密集的炮火","artillery barrage 指炮弹在一段时间内密集落下，形成压倒性的火力覆盖。","an artillery barrage"),e("问题、批评或抱怨密集倾泻","比喻结构 a barrage of... 或 be barraged with... 表示大量言语或请求连续袭来，让人来不及应对。","a barrage of questions","be barraged with complaints")],barren:[e("土地贫瘠、不能产出","修饰 land 时，表示土壤缺乏使作物生长的条件，画面上几乎没有生命产出。","barren land"),e("讨论无结果或内容匮乏","修饰 debate 表示没有产生有用成果；barren of ideas 则直接说明完全缺乏思想内容。","a barren debate","barren of ideas")],barricade:[e("阻断通行的临时障碍","作名词可 erect a barricade、stand behind the barricades；核心是用堆置物或结构封住道路。","erect a barricade","behind the barricades"),e("用障碍物封住入口","作及物动词接 entrance 等位置，表示实际设置障碍阻止他人进入或通过。","barricade the entrance")],barter:[e("不使用货币而直接交换","可 barter goods for services，也可 barter with someone；barter system 指以这种交换方式组织交易的制度。","barter goods for services","a barter system","barter with neighbors")],batch:[e("作为同一轮处理的一批","可指烘焙物、生产材料或同批进入的人；process in batches 强调每一批被统一处理。","a batch of cookies","process in batches","a new batch of recruits")],bathetic:[e("从崇高突降为琐碎或煽情","常修饰 ending、sentimentality、anticlimax，表示原本想制造庄重感动，结果突然落入俗套或滑稽。","a bathetic ending","bathetic sentimentality","a bathetic anticlimax")],bawdy:[e("以性内容制造笑料的粗俗","常修饰 joke、humor、song，语体粗俗但往往带戏谑和喜剧目的。","a bawdy joke","bawdy humor","a bawdy song")],bedeck:[e("以大量醒目装饰点缀","及物动词可 bedeck a place with...；被动 be bedecked in / with 说明人或物被珠宝、花朵、旗帜等华丽覆盖。","bedeck the hall with flowers","be bedecked in jewels","bedecked with flags")],belabor:[e("对一点反复讲得过多","belabor the point / obvious 表示信息已经足够清楚，仍继续重复解释，令表达变得冗长。","belabor the point","belabor the obvious"),e("持续严厉攻击或批评","结构 belabor someone with criticism 表示批评一轮又一轮落在对方身上。","belabor someone with criticism")],beleaguer:[e("以军队包围或围攻","可形容 beleaguered city，也可直接接 defenders，保留敌军从四面包围的历史画面。","a beleaguered city","beleaguer the defenders"),e("使问题从多方面持续困扰","被动 be beleaguered by problems 表示主体同时承受多项压力，像被围困一样难以脱身。","be beleaguered by problems")],belie:[e("以表象掩盖真实情况","主语常是 tone、appearance 等表象；接 truth、age 或 strength 时，表示外观看起来与事实不同，使真实状态不易被看出。","belie the truth","an appearance that belies age"),e("以事实证明预期或说法不成立","主语常是 result、evidence 或 action；belie expectations 表示后来的事实与原有预测相反，从而显示预测不准确。","belie expectations")],bellwether:[e("率先行动并被他人跟随的引领者","用于人或机构时，可指主动设定方向、让同一领域其他成员随后模仿的先锋。","a fashion bellwether"),e("能够预示群体趋势的领先指标","可指企业、地区、选举或人物；其变化不仅自身重要，还被用来判断更大群体接下来会怎样。","an industry bellwether","a political bellwether","serve as a bellwether")],beneficent:[e("主动行善并产生福祉","可修饰 donor、influence、acts，表示人或力量有意给他人带来具体益处。","a beneficent donor","a beneficent influence","beneficent acts")],benign:[e("性情温和、态度友善","修饰 smile 或人物表现时，表示没有威胁，传递温和善意。","a benign smile"),e("不会造成严重伤害","医学上 benign tumor 表示非恶性；修饰 climate 时表示环境温和、危害较小。","a benign tumor","a benign climate")],berate:[e("长时间以强烈语气斥责","及物接人，常用 for 指明过错；公开或被动结构都强调一连串严厉批评落在对方身上。","berate someone for a mistake","publicly berate an employee","be berated by critics")],beseech:[e("在迫切处境下恳切请求","及物可接人加不定式，也可直接接 forgiveness；I beseech you 是正式而感情强烈的恳求句式。","beseech someone to help","beseech forgiveness","I beseech you")],besmirch:[e("以指控或流言玷污名誉","接 reputation、honor 时，表示主动把污点抹到他人的社会评价上。","besmirch a reputation","besmirch someone's honor"),e("把表面弄脏","物理义常见 be besmirched with soot / mud，表示表面沾满污物。","besmirched with soot")],bifurcate:[e("分成两个分支","可及物、可不及物，也可用过去分词作形容词；核心数量明确为 two。","bifurcate into two paths","a bifurcated system","where the river bifurcates")],bigot:[e("顽固抱持偏见且不容异己的人","可由 religious 等词限定偏见领域；把某人称作 bigot 是强烈指控，重点在其拒绝容忍不同群体或观点。","a religious bigot","an intolerant bigot","condemn someone as a bigot")],bland:[e("食物清淡、缺乏味道","修饰 food 时，表示味觉刺激不足，没有明显香料、酸甜或咸味。","bland food"),e("表达或举止温和到乏味","修饰 response、manner 时，表示没有尖锐冲突，却也缺少鲜明个性和吸引力。","a bland response","a bland manner")],blandishment:[e("为说服而使用的甜言蜜语","常用复数，表示把奉承、承诺或温柔劝诱作为手段，推动对方接受请求或采取行动。","resist blandishments","use blandishments to persuade","promises and blandishments")],blasé:[e("因见得太多而不再觉得新鲜","常接 about 或修饰 attitude，表示长期接触享乐、名声或刺激后变得世故冷淡、难以被打动。","blasé about fame","a blasé attitude","become blasé")],blast:[e("突然猛烈的风或冲击","名词 a blast of wind 描述一股短促而强力的气流或冲击。","a blast of wind"),e("以爆破力量炸开","作及物动词时可 blast a tunnel through rock，表示使用爆炸开辟通道。","blast a tunnel through rock"),e("猛烈公开抨击","接 proposal、policy 或 person 时，表示用强烈言辞进行公开攻击。","blast the proposal")],blatant:[e("粗鲁而刺耳地喧嚷","这是较早、现在较少见的声音义；修饰 clamor 等声音时，表示喧响强行抓住注意并令人反感。","a blatant clamor"),e("明显到刺眼且令人反感","常修饰 lie、discrimination、attempt，表示错误或恶意毫无遮掩，任何人都难以忽视。","a blatant lie","blatant discrimination","a blatant attempt")],blazon:[e("公开而醒目地展示或宣扬","可把 name 横跨写在 banner 上，也可把 news 传播开，重点是让信息高调可见。","blazon a name across the banner","blazon the news abroad"),e("用纹章或醒目标志装饰","被动 blazoned with... 描述盾牌等表面带有正式纹章、图案或标志。","a shield blazoned with stars"),e("纹章或纹章的正式文字描述","作名词时，blazon 可指一套纹章，也可指用规范纹章术语写成、足以据此复原图案的精确描述。","a heraldic blazon")],blemish:[e("破坏完美外观的局部瑕疵","作可数名词时指原本良好整体上的小缺点；without blemish 表示没有可见污点或缺陷。","a minor blemish","without blemish"),e("给名誉或整体形象留下污点","作及物动词接 reputation 等抽象对象，表示某个负面事件损害了原本较好的评价。","blemish a reputation")],blight:[e("使植物枯萎的病害","potato blight 指感染作物、令其失去生机并减产的病害。","potato blight"),e("长期摧毁希望或地区生机","作动词可接 hopes；urban blight 则指衰败、空置与破坏在城市地区蔓延。","blight someone's hopes","urban blight")],bliss:[e("近乎完满的极度幸福","可用 pure、domestic 修饰，也可说 a state of bliss，描述没有明显缺憾、令人沉浸的幸福状态。","pure bliss","domestic bliss","a state of bliss")],blithe:[e("轻快、无忧而乐观","a blithe spirit 描写人情绪轻松、仿佛没有负担。","a blithe spirit"),e("对风险漫不经心","blithe disregard 或 blithely assume 表示人轻率地忽略后果，未作应有审慎判断。","blithe disregard","blithely assume")],blueprint:[e("标明建筑或机械细节的技术图纸","实体义指供施工或制造使用的详细图样；现代图纸未必真的以蓝晒工艺制成。","an architectural blueprint"),e("指导后续行动的详细方案","比喻名词义常接 for；可用 draw up 表示把结构、步骤和实施路径系统写成方案。","a blueprint for reform","draw up a blueprint"),e("在行动前把项目详细规划好","作及物动词直接接 project 等对象，表示预先设计其完整结构与步骤，而不只是提出一个想法。","blueprint the project")],blunder:[e("因判断差造成的严重错误","可数名词 a costly blunder 指本可避免、却造成明显后果的愚蠢失误。","a costly blunder"),e("笨拙地闯入或摸索前行","动词接 into 表示误打误撞进入麻烦；接 through 描述看不清方向仍笨拙前进。","blunder into trouble","blunder through the dark")],blunt:[e("刀刃或尖端不锋利","a blunt knife 表示刃口已经钝化，难以顺利切割。","a blunt knife"),e("说话直截了当、不加委婉","be blunt about... 表示把判断直接说出，几乎不作礼貌缓冲。","be blunt about something"),e("使冲击或感受减弱","作动词接 impact、pain 等，表示把原本尖锐强烈的作用削弱。","blunt the impact")],blur:[e("使图像或视觉轮廓模糊","可及物 blur the image，也可不及物 become a blur，表示边缘失去清晰、细节混在一起。","blur the image","become a blur"),e("使概念边界难以区分","接 distinction、line 等抽象对象时，表示原先清楚的分类界线变得不明确。","blur the distinction")],blurt:[e("未经思考便突然说出","最常见结构 blurt out；宾语通常是秘密、答案或本不该立刻说出的信息。","blurt out a secret","blurt out an answer","blurt something out")],bluster:[e("以喧嚷吹嘘和威胁制造强势","可作动词描述大声夸耀、威胁，也可作名词 empty bluster，指出言辞声势很大却缺乏真实力量。","bluster about success","bluster and threaten","empty bluster")],boggle:[e("因代价、困难或疑虑而退缩","不及物接 at / over，表示面对要求或决定时停住，难以继续接受或处理。","boggle at the cost","boggle over a decision"),e("震惊到难以相信","固定表达 the mind boggles 表示事实夸张、复杂或荒唐到思维一时无法容纳。","the mind boggles")],boisterous:[e("喧闹、粗放而精力旺盛","常形容 crowd、laughter、play；声音和动作都很大，欢乐或活力已接近难以约束。","a boisterous crowd","boisterous laughter","boisterous play")],bolster:[e("加强论点或信心","作动词接 argument、confidence，表示提供证据、资源或鼓励，使原本不稳的对象更牢固。","bolster an argument","bolster confidence"),e("长而结实的支撑枕","作可数名词时，a firm bolster 指用于支撑身体的长枕或垫子。","a firm bolster")],bombast:[e("词藻宏大而内容空洞的言辞","常修饰为 political、empty；cut through the bombast 表示越过浮夸措辞，直接看清实际内容。","political bombast","empty bombast","cut through the bombast")],bonhomie:[e("公开、轻松而亲切的友好气氛","可说 an air of bonhomie、public bonhomie，也可用 easy 修饰，强调相处自然愉快、没有紧张防备。","an air of bonhomie","public bonhomie","easy bonhomie")],boo:[e("用嘘声公开表示不满","可作动词直接接人，也可作可数声音名词；in disapproval 明确说明嘘声表达反对或嘲笑。","boo the speaker","a chorus of boos","boo in disapproval")],boon:[e("在特定处境中带来实质帮助的好处","常用 a boon to / for；a great boon 表示某项变化给对象带来明显便利或收益。","a boon to farmers","a great boon"),e("性情愉快、爱社交的伙伴","旧式搭配 a boon companion 指乐于同饮同乐、相处愉快的亲密伙伴。","a boon companion")],boor:[e("粗鲁且缺乏教养的人","可由 insensitive、loud 等词修饰；behave like a boor 表示举止无礼、无视他人感受。","an insensitive boor","behave like a boor","a loud boor")],bootless:[e("无法产生结果、徒劳无益","文学或古雅形容词，通常评价 effort、search；prove bootless 表示最终证明确实没有用。","a bootless effort","a bootless search","prove bootless")],bound:[e("界限、范围","复数 bounds 指可接受或可到达范围；beyond the bounds of reason 表示已经越过理性边界。","beyond the bounds of reason"),e("限定范围","作及物动词时，bound the inquiry 表示给调查设定边界，不让其无限扩张。","bound the inquiry"),e("已经下定决心","固定表达 bound and determined to do 表示决心十分坚定，不会因阻力轻易改变计划。","bound and determined to"),e("必然会发生","结构 be bound to do 表示根据规律、趋势或现有条件，某结果几乎确定会出现。","be bound to succeed"),e("受义务或规则约束","结构 be bound by duty / contract 表示主体因承诺、法律或责任而必须按要求行动。","be bound by duty")],boycott:[e("为施压而集体拒绝购买或参与","可作动词接 product，也可作名词；call for / join a boycott 表示发起或加入有组织的抵制。","boycott a product","call for a boycott","join the boycott")],bracing:[e("直接刺激后使人精神振奋","可形容冷冽海风、快步行走或有挑战性的经历；共同点是刺激清醒感与活力，而非单纯舒适。","bracing sea air","a bracing walk","a bracing challenge")],brake:[e("使车辆或运动减速停止","名词 brakes 是制动装置；动词 brake sharply 表示突然施加制动力。","apply the brakes","brake sharply"),e("抑制抽象进程","比喻短语 put a brake on growth 表示给增长施加减速力量。","put a brake on growth")],brash:[e("自信和冒险超过分寸","常形容年轻领导者、决定或信心，表示行动大胆却缺少判断，容易显得冒失、无礼。","a brash young leader","a brash decision","brash confidence")],brassy:[e("厚脸皮、强势冒进","修饰 manner 时，表示态度大胆得缺少礼貌和羞耻感。","a brassy manner"),e("视觉上俗艳招摇","修饰 display 时，表示颜色、装饰或风格过分明亮炫耀，显得廉价。","a brassy display"),e("声音像黄铜般刺耳响亮","修饰 voice 时，表示音色明亮、尖锐并带金属感。","a brassy voice")],bravado:[e("用夸张勇敢掩盖不安","可说 empty bravado、mask fear with bravado；an act of bravado 指为了展示胆量而作出的冒险姿态。","empty bravado","mask fear with bravado","an act of bravado")],bravura:[e("公开展示高超技巧的精彩表演","可作名词 display bravura，也可作形容词修饰 performance、passage；重点是高难度技巧被华丽呈现。","a bravura performance","a bravura passage","display bravura")],brazen:[e("明知不当仍公然无耻","修饰 lie、attempt 等，表示行为毫无遮掩，行动者也不表现羞愧。","a brazen lie","a brazen attempt"),e("厚着脸皮坚持到底","短语 brazen it out 表示即使受到质疑或揭穿，仍以强硬姿态撑过去。","brazen it out")],breach:[e("违反合同、保密义务或规则","a breach of contract 是名词结构；breach confidentiality 则以动词表示破坏应遵守的义务。","a breach of contract","breach confidentiality"),e("安全边界被突破形成缺口","security breach 指原本应封闭的系统、场所或数据保护出现未经授权的入口。","a security breach")],brevity:[e("表达简短、少而有力","在写作或发言中常作优点评价；for the sake of brevity 表示为避免冗长而省略细节。","the virtue of brevity","for the sake of brevity","remarkable brevity"),e("生命或事件持续时间短暂","此义只强调持续时间很短，不自动包含文字精练或表达清楚。","the brevity of life")],bribe:[e("以不正当利益换取偏袒或违规","可 offer / accept a bribe；作动词接人并可接 into doing，表示用金钱或好处收买对方。","offer a bribe","accept a bribe","bribe someone into silence")],bridle:[e("用于控制马匹的笼头和缰具","作可数名词时，bridle 是套在马头上、连接嚼子与缰绳的控制装置。","put a bridle on a horse"),e("约束情绪或支出","作及物动词接 anger、spending，把控制马匹的缰具图像转为限制冲动和行为。","bridle one's anger","bridle spending"),e("因受冒犯而怒起","不及物结构 bridle at criticism 表示听到批评后立刻昂首、愤怒并表现抵触。","bridle at criticism")],brisk:[e("步伐轻快有力","a brisk walk 表示速度较快、动作有活力。","a brisk walk"),e("商业活动兴旺","brisk trade 表示买卖频繁、市场活跃。","brisk trade"),e("答复干脆而略显生硬","a brisk reply 表示回应简短迅速，语气可能显得不够温和。","a brisk reply")],bristle:[e("因受冒犯而怒起戒备","常用 bristle with anger 或 bristle at a remark，像动物刺毛突然竖起一样表现愤怒。","bristle with anger","bristle at a remark"),e("密集布满突出之物","结构 bristle with weapons 表示武器多而突出，仿佛表面长满硬刺。","bristle with weapons")],brittle:[e("硬而缺乏韧性、容易断裂","brittle glass 受力时不会弯曲缓冲，而会突然破碎。","brittle glass"),e("信心脆弱、容易崩塌","brittle confidence 表示表面坚硬，实际无法承受压力或挫折。","brittle confidence"),e("笑容冷硬而紧张","a brittle smile 表示笑容缺少温暖，仿佛稍受刺激就会碎裂。","a brittle smile")],broach:[e("首次提出敏感话题","及物接 subject、possibility，表示小心开启一项此前尚未正式讨论的话题。","broach a sensitive subject","broach the possibility"),e("启封酒桶","broach a cask 指刺穿或打开桶口，开始取用其中液体；这是较具体的原始动作义。","broach a cask")],bromide:[e("由溴与另一元素或基团形成的化合物","化学义可见 potassium bromide；部分溴化物过去曾被用作镇静剂，这也是后来比喻义的历史桥梁。","potassium bromide"),e("陈腐而空洞的安慰套话","常修饰为 tired、political；offer a bromide 表示用听似正确却没有实际帮助的陈词回应问题。","a tired bromide","offer a bromide","political bromides")],brook:[e("正式地表示容忍","及物动词常见于否定结构 brook no opposition / delay，表示绝不允许某事存在。","brook no opposition","brook no delay"),e("小溪","作可数名词时，a babbling brook 指流水发出轻柔声响的小溪。","a babbling brook")],browbeat:[e("以威吓迫使对方屈服","及物接人，常用 into doing 说明被迫行动；被动 refuse to be browbeaten 表示拒绝受盛气凌人的压力控制。","browbeat a witness","browbeat someone into agreement","refuse to be browbeaten")],bruit:[e("把未经证实的消息传播开","作及物动词，常见被动 be bruited about，也可用 bruit a claim abroad；重点是消息未经核实便进入公共谈论。","be bruited about","bruit a claim abroad","a widely bruited rumor"),e("流传的报告或传闻","这是现在已属古雅的名词义；它指人群中正在流传、但未必经过证实的消息。","the bruit of his resignation"),e("听诊时发现的异常血流杂音","医学名词读 /ˈbruː.i/，指听诊时听到的异常声音，常由血管中的湍流产生。","a carotid bruit")],buck:[e("抵抗趋势、制度或权威","动词可直接接 trend，也可接 against；表示主体顶住主流方向，不肯顺从。","buck the trend","buck against authority"),e("推卸并转交责任","固定短语 pass the buck 表示把本应由自己承担的决定或责任推给别人。","pass the buck")],budge:[e("物理位置移动哪怕一点","常见否定 not budge an inch，表示卡住、过重或受到阻挡的物体完全不动。","budge an inch"),e("改变坚定立场或作出让步","refuse to budge、budge from a position 表示在压力或谈判中仍不改变决定。","refuse to budge","budge from a position")],bulge:[e("表面向外鼓起","可说 a bulge in the wall，也可让 bag 作主语并接 with，表示内部物品把外表撑出凸起。","a bulge in the wall","a bag bulging with books"),e("数量短期突然上升","a bulge in demand 把鼓包图像用于需求在某阶段明显增加。","a bulge in demand"),e("保持暂时优势","较少见的 hold the bulge 指守住已经取得的领先或有利位置。","hold the bulge")],bully:[e("借优势反复欺凌弱者","名词指欺凌者；动词常用 bully someone into doing，表示用威胁强迫对方行动。","a school bully","bully someone into doing something"),e("极好的","旧式形容词用法，如 a bully idea，表示非常好；现代使用罕见，必须依时代语体判断。","a bully idea")],bumptious:[e("自以为重要并强行表现","常形容 official、manner 或说话方式，表示傲慢、爱出风头且不顾他人感受。","a bumptious official","a bumptious manner","sound bumptious")],bungle:[e("因无能或笨拙把事情搞砸","可作动词接 job、investigation，也可作可数名词 a costly bungle 指造成明显后果的处理失误。","bungle the job","bungle an investigation","a costly bungle")],buoy:[e("从下方托住，使物体保持漂浮","物理义直接接 raft 等对象，表示借助浮力防止其下沉。","buoy a raft"),e("支撑情绪或信心使其振作","及物接 spirits、confidence，也常见 be buoyed by support；核心图像是从下方向上托住。","buoy someone's spirits","be buoyed by support","buoy up confidence")],buoyant:[e("有浮力、能够浮起","修饰 material 时，表示密度与结构使其能在液体中保持漂浮。","a buoyant material"),e("情绪轻快或状态有上行动力","a buoyant mood 描写乐观轻快；remain buoyant 也可指市场、信心或人保持活跃。","a buoyant mood","remain buoyant")],burgeon:[e("迅速生长并蓬勃发展","常形容 industry，也可接 into 表示发展成更大形态；rapidly 强调增长速度。","a burgeoning industry","burgeon into a movement","burgeon rapidly")],burlesque:[e("以夸张模仿进行嘲弄","可作名词指讽刺作品，也可作动词模仿 ceremony 等正式形式；imitation 强调作品以变形复制产生滑稽效果。","a political burlesque","burlesque a ceremony","a burlesque imitation")],burnish:[e("摩擦使表面光亮","接 metal 或用 burnished 作定语，表示表面经过摩擦抛光，形成平滑光泽。","burnish the metal","a burnished surface"),e("提升公众形象或声誉","接 reputation 时，把表面增亮转为让社会评价更加光鲜。","burnish a reputation")],buttress:[e("支撑墙体的扶壁","a stone buttress 是从侧面承受压力、加固墙体的建筑结构。","a stone buttress"),e("用证据或理由加强主张","作动词接 argument，或用 be buttressed by evidence，表示给论证增加支撑。","buttress an argument","be buttressed by evidence")],byzantine:[e("制度或过程错综复杂、难以穿行","常修饰 bureaucracy、rules、plot，表示层级、程序与隐秘关系多到令人难以理解或操作。","a byzantine bureaucracy","byzantine rules","a byzantine plot")],cache:[e("为日后使用而隐藏的储备","可作名词 a cache of weapons，也可作动词 cache supplies，表示物资被秘密存放。","a cache of weapons","cache supplies"),e("计算机高速缓存","browser cache 保存近期使用的数据以便快速再次读取；clear the cache 表示清除这些副本。","clear the browser cache")],cachet:[e("附着在名称或物品上的声望","可说 social cachet、add cachet to...；the cachet of exclusivity 表示稀缺与排他性本身带来社会认可。","social cachet","add cachet to","the cachet of exclusivity")],cacophony:[e("多种声音碰撞成刺耳不和谐的整体","常用 a cacophony of...；create 或 rise above the cacophony 描述制造或压过这片混乱声响。","a cacophony of voices","create a cacophony","rise above the cacophony")],cadge:[e("靠讨要或蹭取免费得到","及物接 meal、lift、money；from 指明被索取的人，语气非正式并常暗示占便宜。","cadge a meal","cadge a lift","cadge money from someone")],cajole:[e("用温柔劝说或奉承使人同意","常用 cajole someone into doing；也可 cajole information out of someone，表示以持续哄劝让对方交出信息。","cajole someone into agreeing","cajole information out of someone","gently cajole")],calcify:[e("沉积钙盐而变硬","医学语境中 arteries calcify 表示组织逐渐沉积钙质，失去原有柔韧性。","arteries calcify"),e("思想或制度逐渐僵化","ideas become calcified / calcify into doctrine 表示原本可调整的观点慢慢固定，最终难以改变。","ideas become calcified","calcify into doctrine")],calibrate:[e("依据标准校准仪器","可直接接 instrument，也可接 against a standard，表示调整读数使其与已知基准一致。","calibrate an instrument","calibrate against a standard"),e("精确调节回应的强度","carefully calibrate a response 表示根据对象与风险细调措辞或行动，既不过度也不足。","carefully calibrate a response")],calligraphy:[e("把优美书写作为技艺","可指练习活动、特定文化传统，也可修饰所用工具；核心是字形本身具有审美设计。","practice calligraphy","Chinese calligraphy","a calligraphy brush")],callous:[e("对他人痛苦无感觉、无同情","常修饰 remark、indifference 或作表语，表示态度硬化到不顾他人所受伤害。","a callous remark","callous indifference","seem callous")],callow:[e("年轻且因缺乏经验而不成熟","常修饰 youth、recruit、confidence；重点不是年龄本身，而是新手判断尚未经过现实磨炼。","a callow youth","a callow recruit","callow confidence")],calumniate:[e("以明知不实的恶意言论损害名誉","及物直接接人；publicly 与 attempt to 等结构说明诽谤可能公开发生，也可能只是企图。","calumniate a rival","publicly calumniate someone","attempt to calumniate")],camaraderie:[e("共同经历形成的伙伴情谊","常见 sense of、team camaraderie；build camaraderie 表示通过合作和共同风险逐渐建立信任。","a sense of camaraderie","team camaraderie","build camaraderie")],cameo:[e("名人或重要人物的短暂客串","cameo appearance / brief cameo 指出场很短，却因人物身份或表现而引人注意。","a cameo appearance","a brief cameo"),e("简短而鲜明的人物或场景刻画","a vivid cameo of... 指篇幅不长的文字小品，却能迅速勾出对象特征。","a vivid cameo of village life")],camouflage:[e("融入背景以隐藏实体","wear camouflage 与 natural camouflage 分别指人为服装和生物外观使对象不易被发现。","wear camouflage","natural camouflage"),e("掩饰真实意图","作动词接 intention 时，把改变外观转为隐藏真正目的，使别人难以识别。","camouflage an intention")],canard:[e("被当作事实传播的虚假说法","可修饰为 baseless，也可 spread 或 debunk；它不只是尚未确认，而是经核查站不住脚。","a baseless canard","spread a canard","debunk a canard")],candor:[e("不隐瞒真实判断的坦率","常用 speak with candor；可欣赏某人的坦率，也可用 refreshing 说明这种直言在环境中难得。","speak with candor","appreciate someone's candor","refreshing candor")],canon:[e("共同体承认的正典作品集合","literary / official canon 指被某传统或机构认可、具有权威地位的一组作品。","the literary canon","part of the official canon"),e("权威规则或行为准则","a canon of conduct 指被某群体接受并用来规范行为的一项原则。","a canon of conduct")]};function G(a){return(a.senses||[]).flatMap(t=>t.collocations||[])}function E(a){if(!a||a.number<171||a.number>300)return a;let t=C[a.word];if(!t)return a;let r=G(a),n=new Map(r.map(i=>[i.en,i])),c=new Set,s=t.map((i,l)=>{let N=i.phrases.map(b=>{let d=n.get(b);if(!d)throw new Error(`#${a.number} ${a.word}: missing core-use phrase “${b}”`);if(c.has(b))throw new Error(`#${a.number} ${a.word}: duplicate core-use phrase “${b}”`);return c.add(b),d});return{label:`USE ${l+1}`,title:i.title,explanation:i.explanation,collocations:N,examples:[]}}),h=r.filter(i=>!c.has(i.en));if(h.length)throw new Error(`#${a.number} ${a.word}: unassigned core-use phrases ${h.map(i=>i.en).join(", ")}`);return{...a,senses:s}}var o=(a,t,r,n)=>({title:a,targetForms:t,plain:r,translation:n}),$={61:o("Set 61 · 火星拉票",["canvass","capitulate","caprice","captivate","careworn"],"To canvass Mars, the mayor promised never to capitulate, but on a caprice he wore a singing helmet. The helmet could captivate even the most careworn astronaut.","为了在火星上逐户拉票，市长承诺绝不投降，却一时任性戴上了会唱歌的头盔。那头盔甚至能迷住最忧心憔悴的宇航员。"),62:o("Set 62 · 月球修道院",["cardinal","caricature","carnal","carouse","carp"],"The cardinal rule of the moon monastery banned every caricature of carnal desire. At midnight, however, the monks would carouse and carp about the rule.","月球修道院最重要的规矩禁止一切对肉欲的讽刺夸张画像。然而一到午夜，修士们就会纵酒狂欢，并对这条规矩不停挑刺。"),63:o("Set 63 · 冰龙审判",["carve","cast","castigate","catalyze","catastrophe"],"A chef tried to carve a dragon from ice and cast a parrot as its lawyer. The judge began to castigate him, which seemed to catalyze a kitchen catastrophe.","一名厨师想用冰雕出一条龙，又选派一只鹦鹉担任它的律师。法官开始严厉斥责他，结果仿佛催化了一场厨房大灾难。"),64:o("Set 64 · 猫的菜单",["categorical","catholic","caustic","caveat","cavil"],"A categorical cat with catholic tastes served caustic soup. Its menu carried one caveat: anyone who dared cavil about the flavor had to wash the moon.","一只说一不二、口味广泛的猫端出了腐蚀性浓汤。菜单上附带一条警告：谁敢对味道吹毛求疵，谁就得去清洗月亮。"),65:o("Set 65 · 水泥王位",["cavort","cede","cement","censor","censorious"],"At the royal wedding, penguins cavort until the king agrees to cede his throne to a bucket of cement. A censor deletes the photographs, but a censorious goose reviews the scandal.","在王室婚礼上，企鹅们欢快蹦跳，直到国王同意把王位让给一桶水泥。审查员删掉了照片，可一只好挑剔的鹅仍对这桩丑闻发表评论。"),66:o("Set 66 · 幽灵普查",["censure","census","cessation","chaff","chagrin"],"Parliament met to censure a wizard whose census counted ghosts twice. At the cessation of debate, the ghosts began to chaff the speaker, to his great chagrin.","议会开会谴责一名在人口普查中把幽灵数了两遍的巫师。辩论停止时，幽灵们开始拿议长开玩笑，令他十分懊恼难堪。"),67:o("Set 67 · 隐形旗帜",["chameleon","champion","chaos","charade","charlatan"],"A chameleon offered to champion order during the chaos, but the peace conference was a charade run by a charlatan selling invisible flags.","一只变色龙提出要在混乱中维护秩序，可那场和平会议不过是装模作样，主持它的是一个兜售隐形旗帜的骗子。"),68:o("Set 68 · 山羊护照",["chary","chase","chasm","chauvinistic","check"],"A chary detective refused to chase a goat across a chasm. The goat delivered a chauvinistic speech about mountain animals, so the detective paused to check its passport.","一名谨慎的侦探不肯追着山羊跨越深渊。山羊发表了一番鼓吹山地动物优越性的盲目偏袒演说，于是侦探停下来核查它的护照。"),69:o("Set 69 · 飞天钢琴",["cherubic","chicanery","chide","choleric","chord"],"A cherubic accountant used chicanery to hide a flying piano. His mother came to chide him, but a choleric neighbor struck one furious chord and exposed everything.","一名天使般可爱的会计用诡计藏起了一架会飞的钢琴。他母亲前来轻声责备，可暴躁的邻居弹出一个愤怒的和弦，把一切都暴露了。"),70:o("Set 70 · 星期二密道",["chromatic","chronic","churl","cipher","circuitous"],"A chromatic clock suffered a chronic cough. A churl demanded its secret cipher, so the clock escaped by a circuitous route through Tuesday.","一只五彩时钟患有长期咳嗽。一个粗野之人逼它交出秘密密码，于是时钟沿着一条穿过星期二的迂回路线逃走了。"),71:o("Set 71 · 龙的停车术",["circumlocution","circumscribe","circumspect","circumvent","civility"],"Through endless circumlocution, the mayor tried to circumscribe where dragons could park. A circumspect dragon used a teacup to circumvent the rule and then thanked him with perfect civility.","市长绕着圈子说个没完，试图限定龙可以停车的范围。一条考虑周全的龙用茶杯巧妙绕过规定，随后又彬彬有礼地向他道谢。"),72:o("Set 72 · 月球主权",["claim","clandestine","clarion","clarity","clasp"],"A pirate made a claim to the moon during a clandestine picnic. A clarion trumpet announced the claim with such clarity that he dropped his sandwich and had to clasp the flagpole.","一名海盗在秘密野餐时宣称月亮归自己。一支清亮响亮的号角把这项主张宣布得过分清楚，吓得他掉了三明治，只好紧抱旗杆。"),73:o("Set 73 · 墨水暴雨",["clement","cliché","clog","clot","cloudburst"],"Under a clement sky, a poet shouted a cliché into a drain. The words began to clog the pipe, form a clot of ink, and finally burst out in a cloudburst.","在温和宜人的天空下，诗人冲着下水道喊了一句陈词滥调。那些词开始堵住管道，凝成一团墨块，最后化作一场突然的倾盆暴雨喷涌而出。"),74:o("Set 74 · 布丁竞选",["clout","cloying","clumsy","coagulate","coalesce"],"A pudding with political clout gave a cloying speech. Its clumsy gestures made the cream coagulate, and rival desserts began to coalesce behind it.","一只颇有政治影响力的布丁发表了甜腻做作的演说。它笨拙的手势让奶油凝结起来，竞争甜点们也开始在它身后联合成一体。"),75:o("Set 75 · 奶酪终曲",["coax","coda","coerce","coeval","cogent"],"A mouse tried to coax the opera into adding a cheese-themed coda. The conductor could not coerce the orchestra, but a coeval critic offered a cogent argument for it.","一只老鼠试图哄劝歌剧加入一段奶酪主题的终曲。指挥无法强迫乐团，不过一位与他同时代的评论家提出了有力而令人信服的理由。"),76:o("Set 76 · 巨型葡萄",["cognizant","collapse","collude","colossal","coltish"],"Cognizant that the bridge might collapse, two ants still chose to collude on carrying a colossal grape across it, moving with coltish enthusiasm.","两只蚂蚁明知桥可能倒塌，仍决定暗中合作，把一颗巨型葡萄搬过去，并像小马一样兴奋顽皮地前进。"),77:o("Set 77 · 枕头大使",["coma","combustible","comely","comity","commencement"],"A dragon woke from a coma to discover that its combustible pillow had become a comely ambassador. In the spirit of comity, they scheduled their wedding for commencement day.","一条龙从昏迷中醒来，发现自己易燃的枕头竟成了一位端庄好看的大使。本着友好礼让的精神，他们把婚礼安排在毕业典礼那天。"),78:o("Set 78 · 教授与海盗",["commend","commensurate","commingle","commitment","committed"],"The dean chose to commend salaries commensurate with courage and to commingle professors with pirates. His commitment impressed every committed librarian.","院长决定称赞与勇气相称的薪酬制度，还把教授与海盗充分混在一起。他的投入令每一位忠于职守的图书管理员印象深刻。"),79:o("Set 79 · 茶壶怪物",["commodious","commonsensical","commotion","compendium","complacency"],"In a commodious teapot, a commonsensical mouse heard a commotion and opened a compendium of emergency spells. Its complacency returned when the monster proved to be a raisin.","在一只宽敞舒适的茶壶里，一只很有常识的老鼠听见骚动，便翻开应急咒语汇编。等发现怪物只是一颗葡萄干，它又恢复了自满松懈。"),80:o("Set 80 · 地毯命令",["complaisance","compliant","compliment","comply","compose"],"Through exaggerated complaisance, a robot stayed compliant, delivered a compliment to every chair, and promised to comply with the carpet's demands. It then paused to compose itself.","机器人以夸张的讨好顺从保持听话，向每把椅子送上称赞，还答应遵从地毯的要求。随后它停下来让自己恢复镇定。"),81:o("Set 81 · 压缩雷声",["compound","compress","compromise","compunction","concatenate"],"A chemist made a compound that could compress thunder. Unwilling to compromise, she felt compunction and chose to concatenate every warning label into one kilometre-long sentence.","一名化学家制成了可以压缩雷声的混合物。她不愿妥协，却又良心不安，于是把所有警告标签首尾连接成一句一公里长的话。"),82:o("Set 82 · 镜中小太阳",["concave","conceal","concede","concentrate","concerted"],"A concave mirror tried to conceal a tiny sun. It had to concede that everyone should concentrate on a concerted rescue before the room melted.","一面凹镜试图藏起一颗小太阳。它不得不承认，大家应该集中精力，协调一致地展开营救，以免房间融化。"),83:o("Set 83 · 行星和解",["conciliate","concise","concord","concur","condescending"],"To conciliate the arguing planets, an astronaut gives a concise speech on concord. The planets concur, except for a condescending asteroid that corrects her pronunciation.","为了调和争吵的行星，一名宇航员就和谐一致发表了简洁演说。行星们都表示赞同，只有一颗摆出高人一等姿态的小行星纠正了她的发音。"),84:o("Set 84 · 龙的道歉",["condign","condole","condone","conducive","confident"],"The judge announced condign punishment, then stopped to condole with the guilty dragon. He would not condone theft, but believed warm soup was conducive to a confident apology.","法官宣布了完全应得的惩罚，随后停下来慰问有罪的龙。他不会宽恕偷窃，却相信热汤有助于龙作出充满把握的道歉。"),85:o("Set 85 · 会凝固的河",["confine","confluence","confront","confound","congeal"],"Scientists tried to confine three rivers at their confluence, only to confront a fish whose riddles could confound them and make the water congeal.","科学家试图在三条河的汇合处限制水流，却正面遇上一条会出谜语的鱼；它的谜题既能把他们弄糊涂，也能让河水凝固。"),86:o("Set 86 · 飞行屋顶",["congenial","congruent","conjecture","connive","connoisseur"],"A congenial architect drew congruent castles and offered a conjecture about flying roofs. A fox tried to connive with the builder, but a connoisseur of impossible houses exposed the trick.","一位友善合得来的建筑师画出全等城堡，又提出关于飞行屋顶的猜想。一只狐狸试图与施工者暗中勾结，却被一位不可能房屋鉴赏家识破。"),87:o("Set 87 · 仙人掌会议",["conscientious","consensus","consequence","conservative","conservatory"],"A conscientious cactus called a meeting to reach consensus on the consequence of wearing a conservative hat inside a conservatory; the orchids voted no.","一株认真尽责的仙人掌召集会议，想就“在温室里戴一顶低调保守的帽子会有什么后果”达成共识；兰花们投了反对票。"),88:o("Set 88 · 月光方块",["conserve","considerable","console","consolidate","consonant"],"To conserve a considerable pile of moonlight, the queen asked a clown to console it, consolidate it into cubes, and sing a consonant at each corner.","为了保存一大堆可观的月光，女王让小丑先安慰它，再把它加固成方块，并在每个角上唱一个辅音。"),89:o("Set 89 · 影子政府",["conspicuous","conspire","constitute","constrain","constringe"],"A conspicuous mole planned to conspire with umbrellas, constitute a shadow government, constrain the sun, and constringe every ray into a shoelace.","一只格外显眼的鼹鼠计划与雨伞合谋，组建影子政府，限制太阳，并把每束光都收缩成鞋带。"),90:o("Set 90 · 会笑的蛋糕",["construct","consummate","contagious","contaminate","content"],"A baker tried to construct a consummate cake whose laughter was contagious. One sneeze could contaminate the icing, yet the king remained content with the result.","面包师试图造出一只完美精湛、笑声还会传染的蛋糕。一个喷嚏就可能污染糖霜，可国王仍对结果感到满足。"),91:o("Set 91 · 会扭花的篱笆",["contentious","contiguous","contort","contract","contravene"],"A contentious fence stood between contiguous gardens and began to contort every flower. The owners signed a contract never to contravene the fence's demand for weekly applause.","一堵好争吵的篱笆立在两座相邻花园之间，开始扭曲每一朵花。园主们签下合同，保证绝不违反篱笆提出的每周鼓掌要求。"),92:o("Set 92 · 冰箱疗养",["contrite","contumacious","conundrum","convalesce","convenience"],"A contrite but contumacious camel faced a conundrum: whether to convalesce in the desert or choose the convenience of a refrigerator.","一头真诚悔恨却又顽固抗命的骆驼面临难题：究竟在沙漠里逐渐康复，还是选择冰箱带来的便利。"),93:o("Set 93 · 彩虹公路",["convention","converge","conversant","convert","convex"],"At a convention, five roads converge around a scholar conversant with alchemy. He promised to convert each road into a convex rainbow.","在一场大会上，五条道路汇聚到一名精通炼金术的学者周围。他答应把每条路都转化为一条向外凸起的彩虹。"),94:o("Set 94 · 吊灯抽搐",["convey","conviction","convoke","convoluted","convulsion"],"A pigeon tried to convey its conviction that only owls should convoke parliament. Its convoluted speech triggered a convulsion in the royal chandelier.","一只鸽子试图传达自己的坚定信念：只有猫头鹰才应召集议会。它那错综难懂的演说引发了王室吊灯的一阵剧烈抽搐。"),95:o("Set 95 · 萝卜丰饶角",["coop","copious","coquette","cordon","cornucopia"],"Inside a coop, a poet with copious notes tried to impress a coquette by drawing a cordon around a cornucopia of turnips.","在鸡笼里，一名笔记丰富的诗人为了打动一位卖弄风情的人，给一只装满萝卜的丰饶之角画上了警戒线。"),96:o("Set 96 · 波纹王冠",["coronation","corporeal","corroborate","corrosive","corrugated"],"At the coronation, a corporeal ghost offered documents to corroborate its claim to the throne. The queen sprayed corrosive perfume on the corrugated crown.","在加冕礼上，一个有实体的幽灵拿出文件佐证自己对王位的主张。女王则把腐蚀性香水喷在波纹起伏的王冠上。"),97:o("Set 97 · 狼的旅行箱",["cosmopolitan","cosset","countenance","counterfeit","countermand"],"A cosmopolitan wolf liked to cosset its suitcase and countenance no criticism of it. When a counterfeit passport appeared, the wolf had to countermand the trip.","一只见多识广的世界派狼喜欢娇养自己的旅行箱，也容不得任何批评。假护照出现后，它只得取消先前的旅行命令。"),98:o("Set 98 · 金靴巨龙",["court","covert","covetous","cow","cowardice"],"A prince tried to court a covert dragon but grew covetous of its golden boots. One roar could cow him into admitting his cowardice.","王子试图追求一条隐秘行事的龙，却开始垂涎它的金靴。龙吼一声就能把他吓服，逼他承认自己的懦弱。"),99:o("Set 99 · 松鼠房东",["cower","cozen","cramped","crass","crave"],"Three giants cower while a squirrel tries to cozen them into renting a cramped cave. They call the offer crass but secretly crave the tiny furniture.","三名巨人畏缩着，一只松鼠则试图哄骗他们租下一座狭小拥挤的洞穴。他们嘴上说这项提议粗俗愚钝，心里却十分渴望那些迷你家具。"),100:o("Set 100 · 小溪熨衣",["craven","crease","credence","credulous","creek"],"A craven tailor left a crease in a king's cape and gave credence to a credulous frog's claim that a creek had done the ironing.","一个怯懦的裁缝在国王的披风上留下折痕，竟相信了一只轻信青蛙的说法：衣服是小溪熨的。")};var H={...f,...y,...w,...v,...Z,...k,...S,...x,...j,...T};function O(a=""){return String(a).replace(/(?:[。；]|——)\s*(?:这里)?这?只是[^。；]*(?:声音|发音|近音|谐音|记忆)[^。；]*[。；]?$/u,"。")}function R(a,t){let r=String(a?.contrast||""),n=t?.senses?.[0]?.collocations?.[0],s=/(?:(?:原表|源表).*(?:提示|标识|指向|锚定|锁定|覆盖).*(?:义|核心)|(?:提示|标识)(?:原表|源表)义|是(?:原表|源表)提示|(?:原表|源表)注解覆盖)/.test(r)?`${a.word} 表示“${a.meaningZh||t.coreZh}”；${t.word}${n?.en?` 常见于 ${n.en}`:""}，表示“${t.coreZh}”。`:r.replace(/^(.+?)\s+是(?:原表|源表)[^，；。]{0,20}候选(?:且)?[，,]?\s*/u,"$1 ").replace(/^(?:原表|源表)短语保留(?:了)?(?:词源)?画面[：:]\s*/u,""),h=(a.examples||[]).map(i=>(/\bsource (?:gloss|annotation|note)\b/i.test(String(i?.en||""))||/(?:原表|源表).*(?:提示|标识|指向|锚定|锁定).*(?:义|核心)/.test(String(i?.zh||"")))&&n?.example?{...n.example}:i);return{...a,contrast:s,examples:h}}function U(a){return a&&{...a,comparisons:(a.comparisons||[]).map(t=>R(t,a)),memory:a.memory?{...a.memory,soundZh:O(a.memory.soundZh)}:a.memory}}var q=m.map(a=>{let t=a;return U(A(g(E(p({...t,setId:t.number<=3070?Math.ceil(t.number/5):null,memory:{...t.memory,...z[t.word]||{}}})))))}),B=new Map(q.map(a=>[a.number,a])),I=u.map(a=>({...a,lessons:a.lessons.map(t=>B.get(t.number)||t),story:H[a.id]||$[a.id]||a.story}));var Q=new Map(q.map(a=>[a.number,a])),F=new Map(I.map(a=>[a.id,a]));function M(a){return F.get(Number(a))||I[0]}function pe(a){return Q.get(Number(a))}function ge(a){let t=Number(a);return t===3071?null:F.get(Math.ceil(t/5))||null}function W(a,t){let r=a.lessons.filter(s=>s.number!==t.number).map(s=>s.word),n=(t.number-1)%4,c=r.slice(0,3);return c.splice(n,0,t.word),{options:c,answerIndex:n}}function fe(a){let t=M(a);return t.lessons.flatMap(r=>{let{options:n,answerIndex:c}=W(t,r);return[{id:`context-${r.number}`,type:"Main word · Context",prompt:r.context.prompt,promptZh:r.context.promptZh||"请选择最符合英语语境的本组主词。",options:n,answer:c,explanation:r.context.explanation,explanationZh:r.context.explanationZh||`${r.word}：${r.coreZh}`,wordNumber:r.number},{id:`contrast-${r.number}`,type:"Annotation & synonym contrast",...r.contrastQuiz,promptZh:r.contrastQuiz.promptZh||"请选择最准确的注解词、近义词或易混词。",explanationZh:r.contrastQuiz.explanationZh||`${r.word} 的核心辨析：${r.coreZh}`,wordNumber:r.number}]})}function ye(a){let t=M(a),r=t.story.plain;for(let n of t.story.targetForms){let c=n.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");r=r.replace(new RegExp(`(?<![\\p{L}\\p{N}_])${c}(?![\\p{L}\\p{N}_])`,"iu"),s=>`<mark>${s}</mark>`)}return r}export{fe as createSetQuiz,pe as getLessonByNumber,M as getSet,ge as getSetForLesson,P as lesson3071,q as lessons,ye as markedStory,I as sets,L as tail3071};
